    constexpr size_t CHUNK_MAX = 64 * 1024;
    constexpr size_t GCM_TAG_LEN = 16;
    constexpr size_t GCM_NONCE_LEN = 12;
    constexpr size_t KEY_LEN = 32;
    constexpr size_t V2_HEADER = 32;
    const char* VERSION = "7.0";

    // ------------------------------------------------------------------ api
    struct Api {
        decltype(&BCryptOpenAlgorithmProvider)  OpenProvider = nullptr;
        decltype(&BCryptDecrypt)                Decrypt = nullptr;
        decltype(&BCryptDestroyKey)             DestroyKey = nullptr;
        decltype(&BCryptCloseAlgorithmProvider) CloseProvider = nullptr;
        decltype(&BCryptGenerateSymmetricKey)   GenSymmetricKey = nullptr;
        decltype(&BCryptSetProperty)            SetProperty = nullptr;
    } api{};

    static bool InitCrypto() {
        HMODULE h = LoadLibraryExW(L"bcrypt.dll", NULL,
            LOAD_LIBRARY_SEARCH_SYSTEM32);
        if (!h) return false;
        api.OpenProvider = (decltype(api.OpenProvider))GetProcAddress(h, "BCryptOpenAlgorithmProvider");
        api.Decrypt = (decltype(api.Decrypt))GetProcAddress(h, "BCryptDecrypt");
        api.DestroyKey = (decltype(api.DestroyKey))GetProcAddress(h, "BCryptDestroyKey");
        api.CloseProvider = (decltype(api.CloseProvider))GetProcAddress(h, "BCryptCloseAlgorithmProvider");
        api.GenSymmetricKey = (decltype(api.GenSymmetricKey))GetProcAddress(h, "BCryptGenerateSymmetricKey");
        api.SetProperty = (decltype(api.SetProperty))GetProcAddress(h, "BCryptSetProperty");
        return api.OpenProvider && api.Decrypt && api.DestroyKey &&
            api.CloseProvider && api.GenSymmetricKey && api.SetProperty;
    }

